def dotProduct(vec1, vec2):
    map1 = {i: v for i, v in enumerate(vec1) if v != 0}
    map2 = {i: v for i, v in enumerate(vec2) if v != 0}
    if len(map1) > len(map2):
        map1, map2 = map2, map1
    return sum(v * map2.get(i, 0) for i, v in map1.items())

