import java.util.*;
public class Solution {
    public int dotProduct(int[] vec1, int[] vec2) {
        Map<Integer, Integer> map = new HashMap<>();
        for (int i = 0; i < vec1.length; i++) if (vec1[i] != 0) map.put(i, vec1[i]);
        int result = 0;
        for (int i = 0; i < vec2.length; i++) {
            if (vec2[i] != 0 && map.containsKey(i)) {
                result += vec2[i] * map.get(i);
            }
        }
        return result;
    }
}

