#include <vector>
#include <unordered_map>
using namespace std;
class Solution {
public:
    int dotProduct(vector<int>& vec1, vector<int>& vec2) {
        unordered_map<int, int> map;
        for (int i = 0; i < (int)vec1.size(); i++) if (vec1[i] != 0) map[i] = vec1[i];
        int result = 0;
        for (int i = 0; i < (int)vec2.size(); i++) {
            if (vec2[i] != 0 && map.count(i)) {
                result += vec2[i] * map[i];
            }
        }
        return result;
    }
};
